/* Memphis — 80s postmodern: squiggles, confetti shapes, clashing primaries */
.theme-memphis {
  --bg: oklch(0.97 0.02 90);
  --surface: oklch(1 0 0);
  --surface-2: oklch(0.94 0.09 195);
  --fg: oklch(0.18 0.02 280);
  --fg-muted: oklch(0.45 0.03 280);
  --accent: oklch(0.68 0.23 15);
  --accent-fg: oklch(0.99 0 0);
  --accent-2: oklch(0.78 0.17 195);
  --line: oklch(0.18 0.02 280);
  --success: oklch(0.72 0.19 150);
  --warning: oklch(0.85 0.18 90);
  --danger: oklch(0.62 0.24 25);

  --radius: 0.75rem;
  --radius-sm: 0.375rem;
  --radius-lg: 1.5rem;
  --radius-pill: 9999px;

  --shadow-1: 3px 3px 0 0 var(--fg);
  --shadow-2: 6px 6px 0 0 oklch(0.78 0.17 195);
  --shadow-3: 10px 10px 0 0 oklch(0.85 0.18 90);
  --glow: 0 0 0 3px oklch(0.68 0.23 15 / 40%);

  --border-width: 3px;
  --blur-amount: 0px;

  --font-display: "Bebas Neue", "Archivo", sans-serif;
  --font-body: "Archivo", "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: 0.03em;
  --label-transform: uppercase;
  --label-tracking: 0.16em;

  background-color: var(--bg);
  background-image:
    radial-gradient(circle at 12% 18%, oklch(0.78 0.17 195) 0 8px, transparent 9px),
    radial-gradient(circle at 84% 32%, oklch(0.68 0.23 15) 0 6px, transparent 7px),
    radial-gradient(circle at 30% 78%, oklch(0.85 0.18 90) 0 10px, transparent 11px),
    repeating-linear-gradient(45deg, oklch(0.18 0.02 280 / 6%) 0 6px, transparent 6px 14px);
  background-attachment: fixed;
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-memphis h1,
.theme-memphis h2,
.theme-memphis h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  text-transform: uppercase;
}

/* signature */
.theme-memphis h1 { text-shadow: 4px 4px 0 var(--accent-2); }
.theme-memphis h2 { text-decoration: underline wavy var(--accent) 3px; text-underline-offset: 8px; }
.theme-memphis button:hover { transform: rotate(-1.5deg) scale(1.03); }

/* depth */
.theme-memphis thead th { background: var(--fg); color: var(--bg); text-transform: uppercase; letter-spacing: 0.14em; border-bottom: 4px solid var(--accent); }
.theme-memphis td { border-bottom: 2px dotted var(--fg); }
.theme-memphis tbody tr:hover td { background: oklch(0.94 0.09 195 / 60%); }
.theme-memphis input, .theme-memphis textarea, .theme-memphis select { border: 3px solid var(--line); background: var(--surface); }
.theme-memphis input:focus-visible, .theme-memphis textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: 4px 4px 0 var(--accent-2); transform: rotate(-0.5deg); }
.theme-memphis kbd { font-family: var(--font-mono); border: 2px solid var(--fg); background: var(--warning); padding: 0.1em 0.45em; border-radius: 999px; box-shadow: 2px 2px 0 var(--fg); }
.theme-memphis a { color: var(--fg); font-weight: 700; text-decoration: underline wavy var(--accent-2) 2px; text-underline-offset: 5px; }
.theme-memphis a:hover { text-decoration-color: var(--accent); color: var(--accent); }
.theme-memphis ::selection { background: var(--accent-2); color: var(--fg); }
.theme-memphis ::-webkit-scrollbar { width: 14px; }
.theme-memphis ::-webkit-scrollbar-track { background: var(--bg); background-image: repeating-linear-gradient(45deg, oklch(0.18 0.02 280 / 12%) 0 4px, transparent 4px 10px); }
.theme-memphis ::-webkit-scrollbar-thumb { background: var(--accent); border: 3px solid var(--fg); border-radius: 999px; }
.theme-memphis .label-caps { display: inline-block; transform: rotate(-2deg); background: var(--accent-2); color: var(--fg); padding: 0.1em 0.6em; border: 2px solid var(--fg); border-radius: 999px 0 999px 0; }
.theme-memphis .themed-border { border: 3px solid var(--fg); border-radius: 1.5rem 0.25rem 1.5rem 0.25rem; box-shadow: 6px 6px 0 var(--warning); }
.theme-memphis hr { border: none; height: 6px; background-image: repeating-linear-gradient(90deg, var(--accent) 0 16px, var(--accent-2) 16px 32px, var(--warning) 32px 48px); }

/* alt mode: memphis after dark — chalkboard base, confetti stays lit */
.theme-memphis.alt-mode {
  --bg: oklch(0.2 0.03 280);
  --surface: oklch(0.26 0.03 280);
  --surface-2: oklch(0.32 0.06 195);
  --fg: oklch(0.96 0.02 90);
  --fg-muted: oklch(0.76 0.03 90);
  --line: oklch(0.96 0.02 90);
  --shadow-1: 3px 3px 0 0 oklch(0.1 0.02 280);
  --shadow-2: 6px 6px 0 0 oklch(0.78 0.17 195 / 80%);
  --shadow-3: 10px 10px 0 0 oklch(0.85 0.18 90 / 80%);
  background-image:
    radial-gradient(circle at 12% 18%, oklch(0.78 0.17 195) 0 8px, transparent 9px),
    radial-gradient(circle at 84% 32%, oklch(0.68 0.23 15) 0 6px, transparent 7px),
    radial-gradient(circle at 30% 78%, oklch(0.85 0.18 90) 0 10px, transparent 11px),
    repeating-linear-gradient(45deg, oklch(0.96 0.02 90 / 5%) 0 6px, transparent 6px 14px);
  background-attachment: fixed;
}
.theme-memphis.alt-mode thead th { background: var(--surface-2); color: var(--fg); }
.theme-memphis.alt-mode tbody tr:hover td { background: oklch(0.32 0.06 195 / 60%); }
.theme-memphis.alt-mode kbd { color: oklch(0.18 0.02 280); }
.theme-memphis.alt-mode .label-caps { color: oklch(0.18 0.02 280); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
